import java.util.Scanner;
public class JStars2
{
	public static void main (String[] args)
	{		
		//Paso 1: Leer el numero de filas en el patron de triangulo recto invertido de asteriscos
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese el numero de filas del patron de triangulo recto invertido de asteriscos: ");
		int N = scan.nextInt();
		scan.close();
		//Paso 2: Imprimir las filas en el patron de asteriscos, una por una
		for (int i = 1; i <= N; i++)
		{
			//Paso 2.1: Imprimir los asteriscos en la fila i-esima
			for (int j = 1; j <= N-i+1; j++) {
				System.out.print ("*");
			}
			System.out.println();
		}
	}
}

